js='''
const CART_IDEAS=__CART__,TRAY_IDEAS=__TRAY__, demoLines=__LINES__;
const fmt=c=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(c/100);
let demo={currency:'PHP',item_count:6,total_price:201950,note:'',items:structuredClone(demoLines)};
const nativeFetch=window.fetch.bind(window);
window.fetch=async(url,opts={})=>{if(String(url).includes('/cart')){const body=opts.body?JSON.parse(opts.body):{};if(body.updates)demo.items=demo.items.filter(l=>body.updates[l.key]!==0);if('note'in body)demo.note=body.note;demo.item_count=demo.items.length;demo.total_price=demo.items.reduce((s,l)=>s+l.final_line_price,0);return new Response(JSON.stringify(demo),{headers:{'Content-Type':'application/json'}});}return nativeFetch(url,opts)};
let mode='cart',idea=1,picks=demoLines.slice();
function drawTray(){const el=document.querySelector('#trayHost');const before=picks.reduce((s,l)=>s+l.original_line_price,0),paid=picks.reduce((s,l)=>s+l.final_line_price,0);const rows=picks.map((l,i)=>`<li data-n="${i+1}"><img src="../assets/sample-decant-clear.webp" alt=""><span>${l.product_title}</span><b>${fmt(l.final_line_price)}</b><button data-remove="${l.key}" aria-label="Remove ${l.product_title}">×</button></li>`).join('');const shelf=idea===4?'<div class="shelf">'+picks.map(()=>'<img src="../assets/sample-decant-clear.webp" alt="">').join('')+'</div>':'';const list=[6,7].includes(idea)?`<details><summary>${picks.length} scents selected · View / edit</summary><ol>${rows}</ol></details>`:`<ol>${rows}</ol>`;el.innerHTML=`<div class="tray"><h3>Your vials</h3><p class="meta">Wardrobe six · 6 × 2 ml · ${picks.length} of 6 selected</p>${shelf}${list}<div class="sum"><span>Total</span><strong>${fmt(paid)}</strong></div><p class="saving">Save ${fmt(before-paid)} · 30% on this example set</p><button class="add">${picks.length===6?'Add set to bag':'Pick '+(6-picks.length)+' more'}</button><p class="notice">Example only · This preview does not change your shop or place an order.</p></div>`;el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{picks=picks.filter(l=>l.key!==b.dataset.remove);drawTray()});el.querySelector('.add').onclick=()=>document.querySelector('.demo-status').textContent='Design preview only — no items added.'}
function draw(){document.body.dataset.mode=mode;document.body.dataset.idea=idea;document.querySelector('#cartHost').hidden=mode!=='cart';document.querySelector('#trayHost').hidden=mode!=='tray';document.querySelectorAll('[data-mode-button]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.modeButton===mode));const ideas=mode==='cart'?CART_IDEAS:TRAY_IDEAS;document.querySelector('#options').innerHTML=ideas.map(([n,d],i)=>`<button class="option" data-select="${i+1}" aria-pressed="${idea===i+1}"><span class="number">${String(i+1).padStart(2,'0')}</span><span><strong>${n}${i===0?' · Recommended':''}</strong><small>${d}</small></span></button>`).join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{idea=Number(b.dataset.select);draw()});document.querySelector('#previewTitle').textContent=ideas[idea-1][0];drawTray();const list=document.querySelector('.pcd__set-vials');if(list&&idea===3&&!list.parentElement.matches('details')){const d=document.createElement('details');d.innerHTML='<summary style="min-height:44px;padding:10px 0;cursor:pointer">View 6 scents & savings</summary>';list.before(d);d.append(list)}else if(list&&idea!==3&&list.parentElement.matches('details')){const d=list.parentElement;d.before(list);d.remove()}}
document.querySelectorAll('[data-mode-button]').forEach(b=>b.onclick=()=>{mode=b.dataset.modeButton;idea=1;draw()});
document.addEventListener('DOMContentLoaded',()=>{const drawer=document.querySelector('perfume-cart-drawer');drawer.inert=false;drawer.classList.add('is-open');drawer.load();document.querySelector('.pcd__form').onsubmit=e=>{e.preventDefault();document.querySelector('.demo-status').textContent='Checkout preview only — no order submitted.'};document.querySelector('.pcd__view').onclick=e=>{e.preventDefault();document.querySelector('.demo-status').textContent='View bag preview only.'};draw()});
document.querySelector('#reset').onclick=()=>{picks=demoLines.slice();demo.items=structuredClone(demoLines);demo.item_count=6;demo.total_price=201950;document.querySelector('perfume-cart-drawer').load();draw()};draw();
'''.replace('__CART__',json.dumps(cart)).replace('__TRAY__',json.dumps(tray)).replace('__LINES__',json.dumps(data))
# Keep the production renderer in its comparison frame; only the body portal is disabled.
renderer=(root/'assets/perfume-cart-drawer.js').read_text().replace('if (this.parentElement !== document.body) {', 'if (false) {', 1)
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cart & vial tray · 20 design studies</title>{fonts}<link rel="stylesheet" href="../assets/perfume-tokens.css"><link rel="stylesheet" href="../assets/perfume-cart-drawer.css"><style>{css}</style><header><h1>A smaller bag. A clearer set.</h1><p>Ten cart drawers and ten “Your vials” layouts. Example prices: six 2 ml vials, 30% off, ₱2,019.50 paid.</p><div class="switch"><button data-mode-button="cart" aria-pressed="true">Cart drawer · 10 ideas</button><button data-mode-button="tray" aria-pressed="false">Your vials · 10 ideas</button><button id="reset" class="reset">Reset example</button></div></header><main class="layout"><nav class="options" id="options" aria-label="Design options"></nav><section class="stage"><h2 id="previewTitle"></h2><div class="frame" id="cartHost">{drawer}</div><div class="frame" id="trayHost" hidden></div><p class="demo-status" role="status"></p><p class="preview-note">Design studies only. Option 1 uses the actual updated cart renderer. Checkout and View bag are demonstrations here.</p></section></main><script>{js}</script><script>{renderer}</script></html>'''
(root/'dev/cart-and-tray-ideas.html').write_text(page)
print('Created ten cart drawer and ten vial tray design studies')
